package org.slavicmyths.skim;
import java.util.*;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.saveddata.SavedData;
import org.slavicmyths.bogatyr.*;
import org.slavicmyths.marinka.*;
import org.slavicmyths.finist.*;
/** Supplements existing canonical UUID maps with recalled snapshots; never loads distant chunks. */
public final class HeroCalls extends SavedData {
 public final Map<UUID,UUID> alyosha=new HashMap<>(),finist=new HashMap<>();
 public final Map<String,CompoundTag> resting=new HashMap<>();
 public final Map<UUID,CompoundTag> dormant=new HashMap<>(),finistDormant=new HashMap<>();
 public final Set<UUID> retired=new HashSet<>();
 private final Map<UUID,Long> departures=new HashMap<>();
 public static HeroCalls get(ServerLevel w){return w.getServer().overworld().getDataStorage().computeIfAbsent(new Factory<>(HeroCalls::new,HeroCalls::load),"slavicmyths_hero_calls_173");}
 public static HeroCalls load(CompoundTag n,HolderLookup.Provider p){var d=new HeroCalls();for(var t:n.getList("Alyosha",Tag.TAG_COMPOUND)){var a=(CompoundTag)t;d.alyosha.put(a.getUUID("Owner"),a.getUUID("Entity"));}for(var t:n.getList("Finist",Tag.TAG_COMPOUND)){var a=(CompoundTag)t;d.finist.put(a.getUUID("Owner"),a.getUUID("Entity"));}var s=n.getCompound("Resting");for(var k:s.getAllKeys())d.resting.put(k,s.getCompound(k));s=n.getCompound("Dormant");for(var k:s.getAllKeys())d.dormant.put(UUID.fromString(k),s.getCompound(k));s=n.getCompound("FinistDormant");for(var k:s.getAllKeys())d.finistDormant.put(UUID.fromString(k),s.getCompound(k));for(var t:n.getList("Retired",Tag.TAG_STRING))d.retired.add(UUID.fromString(t.getAsString()));return d;}
 @Override public CompoundTag save(CompoundTag n,HolderLookup.Provider p){var a=new ListTag();alyosha.forEach((k,v)->{var t=new CompoundTag();t.putUUID("Owner",k);t.putUUID("Entity",v);a.add(t);});n.put("Alyosha",a);var fs=new ListTag();finist.forEach((k,v)->{var t=new CompoundTag();t.putUUID("Owner",k);t.putUUID("Entity",v);fs.add(t);});n.put("Finist",fs);var s=new CompoundTag();resting.forEach(s::put);n.put("Resting",s);s=new CompoundTag();for(var e:dormant.entrySet())s.put(e.getKey().toString(),e.getValue());n.put("Dormant",s);var fd=new CompoundTag();for(var e:finistDormant.entrySet())fd.put(e.getKey().toString(),e.getValue());n.put("FinistDormant",fd);var retiredTags=new ListTag();retired.forEach(id->retiredTags.add(StringTag.valueOf(id.toString())));n.put("Retired",retiredTags);return n;}
 public static Map<UUID,UUID> map(ServerLevel w,String id){return switch(id){case "ilya_muromets"->BogatyrLedger.get(w).heroes;case "dobrynya_nikitich"->WitchYard.get(w.getServer().overworld()).heroes;case "finist"->get(w).finist;default->get(w).alyosha;};}
 public static boolean battleLocked(ServerPlayer p){var v=SkimValley.get(p.serverLevel());var near=v.near(p.position());var y=WitchYard.get(p.serverLevel().getServer().overworld());var yard=y.near(p.position());return org.slavicmyths.kalin.KalinEncounter.get(p.serverLevel()).owner(p.getUUID())!=null||org.slavicmyths.kalin.KalinEncounter.get(p.serverLevel()).nearBattle(p.serverLevel(),p.position())||KartausEncounter.get(p.serverLevel()).owner(p.getUUID())!=null||KartausEncounter.get(p.serverLevel()).near(p.serverLevel(),p.position())||v.lock(p.getUUID())!=null||(near!=null&&(near.status==SkimValley.Status.STARTING||near.status==SkimValley.Status.ACTIVE))||y.lock(p.getUUID())!=null||(yard!=null&&yard.status==WitchYard.Status.COMBAT)||BogatyrLedger.active(p);}
 public static int count(ServerPlayer p){int n=0;for(var id:List.of("ilya_muromets","dobrynya_nikitich","alyosha_popovich","finist"))if(map(p.serverLevel(),id).containsKey(p.getUUID()))n++;return n;}
 public static Entity loaded(ServerPlayer p,String id){var uuid=map(p.serverLevel(),id).get(p.getUUID());if(uuid==null)return null;for(var w:p.serverLevel().getServer().getAllLevels()){var e=w.getEntity(uuid);if(e!=null)return e;}return null;}
 public static void dirty(ServerLevel w){get(w).setDirty();BogatyrLedger.get(w).setDirty();WitchYard.get(w.getServer().overworld()).setDirty();}
 public static void message(ServerPlayer p,String k){long now=p.level().getGameTime();var n=p.getPersistentData();if(now<n.getLong("HeroCallMessageUntil"))return;n.putLong("HeroCallMessageUntil",now+60);p.sendSystemMessage(net.minecraft.network.chat.Component.translatable("message.slavicmyths."+k));}
 public static void messageOwner(AlyoshaEntity a,String k){if(a.level() instanceof ServerLevel w&&a.owner!=null){var p=w.getServer().getPlayerList().getPlayer(a.owner);if(p!=null)message(p,k);}}
 public static boolean safeSpot(ServerLevel w,net.minecraft.world.phys.Vec3 at,double width,double height){if(at==null)return false;var box=new net.minecraft.world.phys.AABB(at.x-width/2,at.y,at.z-width/2,at.x+width/2,at.y+height,at.z+width/2);for(var q:net.minecraft.core.BlockPos.betweenClosed(net.minecraft.core.BlockPos.containing(box.minX,box.minY,box.minZ),net.minecraft.core.BlockPos.containing(box.maxX-.001,box.maxY-.001,box.maxZ-.001))){if(!w.hasChunkAt(q)||!w.getWorldBorder().isWithinBounds(q)||!w.getFluidState(q).isEmpty()||w.getBlockState(q).is(net.minecraft.world.level.block.Blocks.FIRE)||w.getBlockState(q).is(net.minecraft.world.level.block.Blocks.SOUL_FIRE)||w.getBlockState(q).is(net.minecraft.world.level.block.Blocks.WITHER_ROSE)||w.getBlockState(q).is(net.minecraft.world.level.block.Blocks.SWEET_BERRY_BUSH))return false;if(q.getY()==net.minecraft.core.BlockPos.containing(at).getY()&&!org.slavicmyths.sivka.SivkaWhistle.safeFloor(w,q.below()))return false;}return w.noCollision(box);}
 public static void sleep(AlyoshaEntity a){if(a.owner==null||!(a.level() instanceof ServerLevel w))return;var n=new CompoundTag();a.saveWithoutId(n);get(w).dormant.put(a.owner,n);get(w).setDirty();a.discard();}
 public static void sleepFinist(FinistEntity f){if(f.owner==null||!(f.level() instanceof ServerLevel w))return;var n=new CompoundTag();f.saveWithoutId(n);get(w).finistDormant.put(f.owner,n);get(w).setDirty();f.discard();}
 public void recover(ServerLevel w){if(w.getGameTime()%20==0)for(var entry:new ArrayList<>(finistDormant.entrySet())){var p=w.getServer().getPlayerList().getPlayer(entry.getKey());if(p==null)continue;var n=entry.getValue();n.putFloat("Health",Math.min(119,n.getFloat("Health")+8));setDirty();if(org.slavicmyths.kalin.KalinEncounter.get(w).owner(p.getUUID())!=null||KartausEncounter.get(w).owner(p.getUUID())!=null||n.getFloat("Health")<119)continue;var at=BogatyrLedger.safe(p.serverLevel(),p.position(),.76,3,3);if(!safeSpot(p.serverLevel(),at,.76,2.25))continue;var f=FinistContent.FINIST.get().create(p.serverLevel());f.load(n);f.encounter=null;f.moveTo(at.x,at.y,at.z,p.getYRot()+180,0);if(p.serverLevel().addFreshEntity(f)){finist.put(p.getUUID(),f.getUUID());finistDormant.remove(p.getUUID());setDirty();}}if(w.getGameTime()%40!=0)return;for(var entry:new ArrayList<>(dormant.entrySet())){var p=w.getServer().getPlayerList().getPlayer(entry.getKey());if(p==null)continue;var n=entry.getValue();n.putFloat("Health",Math.min(122.5F,n.getFloat("Health")+4));setDirty();if(org.slavicmyths.kalin.KalinEncounter.get(w).owner(p.getUUID())!=null||SkimValley.get(w).lock(p.getUUID())!=null)continue;var at=BogatyrLedger.safe(p.serverLevel(),p.position(),.72,3,3);if(at==null)continue;var h=SkimContent.ALYOSHA.get().create(p.serverLevel());h.load(n);h.arena=null;h.moveTo(at.x,at.y,at.z,p.getYRot()+180,0);if(p.serverLevel().addFreshEntity(h)){alyosha.put(p.getUUID(),h.getUUID());dormant.remove(p.getUUID());setDirty();}}}
 public void reconcile(Entity e){if(!e.getPersistentData().getBoolean("HeroRecalling")||!(e.level() instanceof ServerLevel w))return;UUID owner=e instanceof IlyaEntity a?a.owner:e instanceof DobrynyaEntity a?a.owner:e instanceof AlyoshaEntity a?a.owner:e instanceof FinistEntity a?a.owner:null;if(owner==null)return;String id=e instanceof IlyaEntity?"ilya_muromets":e instanceof DobrynyaEntity?"dobrynya_nikitich":e instanceof FinistEntity?"finist":"alyosha_popovich";if(resting.containsKey(owner+"/"+id))departures.put(e.getUUID(),w.getGameTime()+1);}
 public static boolean toggle(ServerPlayer p,String id){
  if(!p.isAlive()||p.isSpectator())return false;
  var w=p.serverLevel();var d=get(w);var maps=map(w,id);String key=p.getUUID()+"/"+id;
  if(maps.containsKey(p.getUUID())){
   if(battleLocked(p)){message(p,"summon.battle_locked");return false;}
   var e=loaded(p,id);if(!(e instanceof LivingEntity h)||e.level()!=w||d.departures.containsKey(e.getUUID())){message(p,"summon.already_present");return false;}
   var n=new CompoundTag();h.saveWithoutId(n);d.resting.put(key,n);d.departures.put(e.getUUID(),w.getGameTime()+18);h.getPersistentData().putBoolean("HeroRecalling",true);if(h instanceof Mob m){m.getNavigation().stop();m.setTarget(null);}if(h instanceof AlyoshaEntity a)a.begin(SkimAction.RECALL);if(h instanceof FinistEntity a)a.begin(FalconAction.RECALL);d.setDirty();return true;
  }
  if(!StoryPolicy.canSummon(p,id))return false;
  if(count(p)>=2){message(p,"summon.party_full");return false;}
  if(id.equals("dobrynya_nikitich")&&!org.slavicmyths.progression.Knowledge.knows(p,"first_book_entry")&&!p.getInventory().contains(new net.minecraft.world.item.ItemStack(org.slavicmyths.registry.ModItems.LORE_BOOK.get()))&&!p.hasPermissions(2)){message(p,"summon.locked");return false;}
  float width=id.equals("finist")?.76F:id.equals("ilya_muromets")?.93F:id.equals("dobrynya_nikitich")?.8F:.72F;float height=id.equals("finist")?2.2F:id.equals("ilya_muromets")?2.45F:id.equals("dobrynya_nikitich")?2.2F:2.15F;
  var at=BogatyrLedger.safe(w,p.position(),width,Math.max(3,height),3);if(!safeSpot(w,at,width,Math.max(3,height))){message(p,"summon.unsafe");return false;}
  LivingEntity h=switch(id){case "ilya_muromets"->BogatyrContent.ILYA.get().create(w);case "dobrynya_nikitich"->MarinkaContent.DOBRYNYA.get().create(w);case "finist"->FinistContent.FINIST.get().create(w);default->SkimContent.ALYOSHA.get().create(w);};if(h==null)return false;
  var snapshot=d.resting.get(key);if(snapshot!=null)h.load(snapshot.copy());h.setUUID(UUID.randomUUID());h.getPersistentData().remove("HeroRecalling");
  if(h instanceof FinistEntity a){a.owner=p.getUUID();a.begin(FalconAction.ARRIVE);}if(h instanceof IlyaEntity a)a.owner=p.getUUID();if(h instanceof DobrynyaEntity a)a.owner=p.getUUID();if(h instanceof AlyoshaEntity a){a.owner=p.getUUID();a.begin(SkimAction.ARRIVE);}
  h.moveTo(at.x,at.y,at.z,p.getYRot()+180,0);h.getPersistentData().putLong("HeroArrivingUntil",w.getGameTime()+24);if(!w.addFreshEntity(h))return false;maps.put(p.getUUID(),h.getUUID());d.resting.remove(key);dirty(w);
  w.sendParticles(net.minecraft.core.particles.ParticleTypes.END_ROD,at.x,at.y+1,at.z,16,.3,.7,.3,.02);return true;
 }
 public void departures(net.minecraft.server.MinecraftServer server){long now=server.overworld().getGameTime();for(var entry:new ArrayList<>(departures.entrySet())){if(now<entry.getValue())continue;Entity entity=null;for(var w:server.getAllLevels()){var found=w.getEntity(entry.getKey());if(found!=null){entity=found;break;}}if(entity!=null){UUID owner=entity instanceof IlyaEntity a?a.owner:entity instanceof DobrynyaEntity a?a.owner:entity instanceof AlyoshaEntity a?a.owner:entity instanceof FinistEntity a?a.owner:null;String id=entity instanceof IlyaEntity?"ilya_muromets":entity instanceof DobrynyaEntity?"dobrynya_nikitich":entity instanceof FinistEntity?"finist":"alyosha_popovich";if(owner!=null)map(server.overworld(),id).remove(owner,entry.getKey());entity.discard();}else{for(var snap:resting.entrySet())if(snap.getValue().hasUUID("UUID")&&entry.getKey().equals(snap.getValue().getUUID("UUID"))){var pieces=snap.getKey().split("/");map(server.overworld(),pieces[1]).remove(UUID.fromString(pieces[0]),entry.getKey());retired.add(entry.getKey());break;}}departures.remove(entry.getKey());dirty(server.overworld());}}
}
